CREATE TABLE public.email_send_state (id INT PRIMARY KEY DEFAULT 1 CHECK (id = 1), retry_after_until TIMESTAMPTZ, batch_size INTEGER NOT NULL DEFAULT 10, send_delay_ms INTEGER NOT NULL DEFAULT 200, auth_email_ttl_minutes INTEGER NOT NULL DEFAULT 15, transactional_email_ttl_minutes INTEGER NOT NULL DEFAULT 60, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
GRANT ALL ON public.email_send_state TO service_role;
ALTER TABLE public.email_send_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Service role can manage send state" ON public.email_send_state FOR ALL TO service_role USING (true) WITH CHECK (true);
